class TokenBucket {
  constructor({ capacity, refillPerSec, now }) {
    this.capacity = capacity;
    this.refillPerSec = refillPerSec;
    this.now = now;
    this.tokens = capacity;      // start full: allows an initial burst
    this.last = now();
  }

  refill() {
    const t = this.now();
    const elapsedMs = t - this.last;
    this.last = t;
    this.tokens = Math.min(this.capacity, this.tokens + (elapsedMs / 1000) * this.refillPerSec);
  }

  tryRemove(cost = 1) {
    this.refill();
    if (this.tokens >= cost) {
      this.tokens -= cost;
      return { allowed: true, remaining: Math.floor(this.tokens) };
    }
    const retryAfterMs = cost > this.capacity
      ? Infinity
      : Math.ceil(((cost - this.tokens) / this.refillPerSec) * 1000);
    return { allowed: false, remaining: Math.floor(this.tokens), retryAfterMs };
  }
}

class TenantLimiter {
  constructor(configFor, now) {
    this.configFor = configFor;
    this.now = now;
    this.buckets = new Map();
  }
  check(tenantId, cost = 1) {
    let b = this.buckets.get(tenantId);
    if (!b) {
      b = new TokenBucket({ ...this.configFor(tenantId), now: this.now });
      this.buckets.set(tenantId, b);
    }
    return b.tryRemove(cost);
  }
}

