let t = 0;
const b = new TokenBucket({ capacity: 3, refillPerSec: 1, now: () => t });
assertEqual(b.tryRemove(), { allowed: true, remaining: 2 });
assertEqual(b.tryRemove(), { allowed: true, remaining: 1 });
assertEqual(b.tryRemove(), { allowed: true, remaining: 0 });
assertEqual(b.tryRemove().allowed, false);

let t = 0;
const b = new TokenBucket({ capacity: 5, refillPerSec: 2, now: () => t });
for (let i = 0; i < 5; i++) b.tryRemove();
assertEqual(b.tryRemove().allowed, false);
t = 1000; // 2 new tokens
assertEqual(b.tryRemove().allowed, true);
assertEqual(b.tryRemove().allowed, true);
assertEqual(b.tryRemove().allowed, false);

let t = 0;
const b = new TokenBucket({ capacity: 4, refillPerSec: 10, now: () => t });
b.tryRemove(4);
t = 60 * 60 * 1000;
assertEqual(b.tryRemove(), { allowed: true, remaining: 3 });

let t = 0;
const b = new TokenBucket({ capacity: 10, refillPerSec: 2, now: () => t });
b.tryRemove(9); // 1 left
assertEqual(b.tryRemove(4), { allowed: false, remaining: 1, retryAfterMs: 1500 });
t = 1500;
assertEqual(b.tryRemove(4), { allowed: true, remaining: 0 });

let t = 0;
const b = new TokenBucket({ capacity: 2000, refillPerSec: 100, now: () => t });
assertEqual(b.tryRemove(1200), { allowed: true, remaining: 800 });
const r = b.tryRemove(1200);
assertEqual(r.allowed, false);
assertEqual(r.retryAfterMs, 4000);

let t = 0;
const b = new TokenBucket({ capacity: 100, refillPerSec: 10, now: () => t });
assertEqual(b.tryRemove(101), { allowed: false, remaining: 100, retryAfterMs: Infinity });
assertEqual(b.tryRemove(100).allowed, true, 'the failed request must not take tokens');

let t = 0;
const plans = { acme: { capacity: 2, refillPerSec: 1 }, bigco: { capacity: 5, refillPerSec: 5 } };
const lim = new TenantLimiter((id) => plans[id], () => t);
assertEqual(lim.check('acme').allowed, true);
assertEqual(lim.check('acme').allowed, true);
assertEqual(lim.check('acme').allowed, false, 'acme is out');
for (let i = 0; i < 5; i++) assertEqual(lim.check('bigco').allowed, true, 'bigco unaffected by acme');
assertEqual(lim.check('bigco').allowed, false);
t = 1000;
assertEqual(lim.check('acme').remaining, 0);
assertEqual(lim.check('bigco', 3), { allowed: true, remaining: 2 });
